def unpack(d):
 d=Path(d).resolve();d.mkdir(parents=True,exist_ok=True)
 for p,c in F.items():(d/p).parent.mkdir(parents=True,exist_ok=True);(d/p).write_text(base64.b64decode(c).decode(),encoding="utf-8")
 print(f'Created {len(F)} files in {d}')

if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('-o','--output',default='sn_extract');a=p.parse_args();unpack(a.output)
